window.L5R_CHARACTER = {"slug":"shinjo-anzu","name":"Shinjō Anzu","clan":"Unicorn","family":"Shinjo","region":null,"upbringing":null,"origin_type":null,"school":"Iuchi Meishodo Master School","role":"Artisan","bucket":null,"campaign":"The Fragile Peace","status":null,"accent":null,"portrait":"src/portraits/shinjo-anzu.webp","concept":null,"summary":null,"tier_count":2,"xp_min":0,"xp_max":104,"provenance":"archive","product":null,"twenty_questions":{"template":"core","generated":true,"steps":{"step1":{"answers":{"clan":"Unicorn","ring":"water","skill":"survival","social_status":30},"picks":{}},"step2":{"answers":{"family":"Shinjo","ring":"fire","skill1":"sentiment","skill2":"survival","wealth":8,"social_glory":44},"picks":{}},"step3":{"answers":{"school":"Iuchi Meishodo Master School","roles":"Artisan","ring1":"earth","ring2":"water","skill1":"aesthetics","skill2":"design","skill3":"theology","social_honor":40},"picks":{"techniques":["Jurōjin’s Balm","The Rushing Wave","Commune with the Spirits","Ancestry Unearthed"],"school_ability":["The Way of Names"],"equipment":["Ceremonial Clothes","Traveling Clothes","Wakizashi","Horsebow","Calligraphy Set","Traveling pack"]}},"step4":{"answers":{"stand_out":"The Way of Names uses the element of the practitioner's choice, and most masters use Earth to settle a spirit into place or Void to meet it on its own terms. Anzu uses Fire: she doesn't settle the spirit, she inflames it into wanting to be there. It's faster, it takes worse, and the talismans that survive it have vocal opinions.","ring":"fire"},"picks":{}},"step5":{"answers":{"social_giri":"Her giri is to Shinjo Altansarnai, Khan of Khans and daimyō of the Shinjo: she makes meishōdō for the family's own use, issued where they are needed rather than given where they are wanted."},"picks":{}},"step6":{"answers":{"social_ninjo":"She wants children and has not been able to have them."},"picks":{}},"step7":{"answers":{"clan_relations":"She stands well with the Unicorn and is called auntie by half of them, including men older than she is, which is usually a courtesy.","social_add_glory":5},"picks":{}},"step8":{"answers":{"bushido":"She holds Compassion first and Honour last, having spent enough time putting bushi back together to conclude that most of what the code asks of them on a field is foolishness.","skill":"medicine","social_add_honor":0,"tenet_paramount":"Compassion","tenet_less_significant":"Honour"},"picks":{}},"step9":{"answers":{"success":"A meishōdō that fails does not merely stop working; it lets something out. Anzu made the browband Ping has worn since Shinjo Altansarnai first rode her, and in all those years it has needed neither repair nor replacement — which is why the word the family uses for her work is not clever but reliable, and why she is the one they send for when the thing must not fail."},"picks":{"distinction":["Famously Reliable"]}},"step10":{"answers":{"difficulty":"The family's talismans are never finished, only sufficient, and Anzu keeps a running count in her head of which ones are ageing and who is carrying them; anything else has to be done around it, and the list is never completed."},"picks":{"adversity":["Encompassing Duty"]}},"step11":{"answers":{"calms":"Occasionally she is able to cook outside for whoever is there — a pot big enough for everyone, and the children eating standing up between rides."},"picks":{"passion":["Hot Pot"]}},"step12":{"answers":{"worries":"The Phoenix decide what counts as proper practice and the court decides what the Emperor hears, and the Iuchi way answers to neither on its own merits. Anzu assumes any authority she has not yet met has already been told something about meishōdō, and it is unlikely to have been kind, or even true."},"picks":{"anxiety":["Conspiracy"]}},"step13":{"answers":{"most_learn":"She and all eight of her siblings were delivered by the same old Ujik woman, who stayed long enough afterwards to teach Anzu what she knew: how a birth goes wrong and how early it can be read, which fevers in a child are worth waking the ordu for, and the names of the Ten Lords of Death, of whom the Child Bearer is one. Anzu is who they send for when a child is coming. She has never had one."},"picks":{"advantage":["Skilled Midwife"]}},"step14":{"answers":{"first_sight":"Broad-faced and weathered past her years, with the grey starting to come in at the temples and her hair worn long and loose the way riders wear it rather than pinned the way the Iuchi school prefers. Her hands are marked across the backs and knuckles from wire and hot metal, and she wears her own work — braided metal at the ears and throat."},"picks":{}},"step15":{"answers":{"stress":"She yells and invents her own very colourful profanity."},"picks":{}},"step16":{"answers":{"relations":"Shinjo Harunobu — her younger brother. Left for the Crab at about nine and has been a stranger to the family since; she made him Musubi.\n\nShinjo Altansarnai — Khan of Khans and daimyō of the Shinjo, Anzu's lord.\n\nThe old Ujik midwife — delivered Anzu and all nine of them, taught her what she knows.\n\nThe children of the ordu — auntie to all of them."},"picks":{"item":["Herbal Medicines"]}},"step17":{"answers":{"parents_pov":"The Iuchi mark their students young, and the family gave her up the year she was marked. Before that she was her father's girl: the horse-lines and the forge, wire and hooves and the fitting of tack, and both her parents will still tell you she was better with a hammer at eleven than a smith's apprentice — which is the nearest either of them comes to saying they would rather have kept her.","skill":"smithing"},"picks":{}},"step18":{"answers":{"heritage_name":"She is named after her grandmother's spirit companion, and befittingly it seems a spirit has chosen her as well, although its strange powers convey the Void.","heritage_1":9,"heritage_2":10,"heritage_add_honor":0,"heritage_add_glory":-3,"heritage_add_status":3},"picks":{"heritage_item":["Sight beyond Existence"]}},"step19":{"answers":{"firstname":"Anzu"},"picks":{}},"step20":{"answers":{"death":"She will receive a great vision while riding, and will perish from the fall off her horse."},"picks":{}}}},"notes":"","bio":"","published":null,"demeanor":null,"relationships":null,"curriculum":[{"rank":1,"kind":"Skill Group","group":null,"label":"Scholar Skills","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Courtesy","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Design","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Survival","prereq":false},{"rank":1,"kind":"Tech. Grp.","group":"invocation","label":"Rank 1 Water Invocations","prereq":false},{"rank":1,"kind":"Technique","group":"invocation","label":"Sympathetic Energies","prereq":true},{"rank":1,"kind":"Technique","group":"ritual","label":"Cleansing Rite","prereq":false},{"rank":2,"kind":"Skill Group","group":null,"label":"Martial Skills","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Design","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Theology","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Survival","prereq":false},{"rank":2,"kind":"Tech. Grp.","group":"invocation","label":"Rank 1–2 Earth Invocations","prereq":false},{"rank":2,"kind":"Technique","group":"invocation","label":"Hands of the Tides","prereq":true},{"rank":2,"kind":"Technique","group":"shuji","label":"Artisan’s Appraisal","prereq":false},{"rank":3,"kind":"Skill Group","group":null,"label":"Artisan Skills","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Performance","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Survival","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Theology","prereq":false},{"rank":3,"kind":"Tech. Grp.","group":"ritual","label":"Rank 1–3 Rituals","prereq":false},{"rank":3,"kind":"Technique","group":"invocation","label":"Rise, Earth","prereq":true},{"rank":3,"kind":"Technique","group":"shuji","label":"Dazzling Performance","prereq":false},{"rank":4,"kind":"Skill Group","group":null,"label":"Social Skills","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Medicine","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Survival","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Theology","prereq":false},{"rank":4,"kind":"Tech. Grp.","group":"invocation","label":"Rank 1–4 Air Invocations","prereq":false},{"rank":4,"kind":"Technique","group":"shuji","label":"Rouse the Soul","prereq":true},{"rank":4,"kind":"Technique","group":"shuji","label":"A Samurai’s Fate","prereq":false},{"rank":5,"kind":"Skill Group","group":null,"label":"Artisan Skills","prereq":false},{"rank":5,"kind":"Skills","group":null,"label":"Culture","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Survival","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Theology","prereq":false},{"rank":5,"kind":"Tech. Grp.","group":"shuji","label":"Rank 1–5 Earth Shūji","prereq":false},{"rank":5,"kind":"Technique","group":"invocation","label":"The Soul’s Blade","prereq":false},{"rank":5,"kind":"Technique","group":"invocation","label":"Ever-Changing Waves","prereq":false}],"title_curricula":{},"legacies":[],"tiers":[{"xp":0,"label":null,"rank":1,"school":"Iuchi Meishodo Master School","foundry_id":"d2MPs8wj7KsCV5w7","rings":{"air":1,"earth":2,"fire":3,"water":3,"void":1},"skills":{"artisan":{"aesthetics":1,"composition":0,"design":1,"smithing":1},"martial":{"fitness":0,"melee":0,"ranged":0,"unarmed":0,"meditation":0,"tactics":0},"scholar":{"culture":0,"government":0,"medicine":1,"sentiment":1,"theology":1},"social":{"command":0,"courtesy":0,"games":0,"performance":0},"trade":{"commerce":0,"labor":0,"seafaring":0,"skulduggery":0,"survival":2}},"social":{"honor":40,"glory":46,"status":33,"ninjo":"She wants children and has not been able to have them.","giri":"Her giri is to Shinjo Altansarnai, Khan of Khans and daimyō of the Shinjo: she makes meishōdō for the family's own use, issued where they are needed rather than given where they are wanted.","bushido_tenets":{"paramount":"Compassion","less_significant":"Honour"}},"derived":{"endurance":10,"composure":10,"focus":4,"vigilance":2,"void_points":1},"money":{"zeni":0,"koku":8,"bu":0},"advancements":[],"techniques":[{"name":"Jurōjin’s Balm","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"invocation","rank":1,"description":"<ul><li>Jurōjin, guardian of longevity, health, and physical wellbeing, is one of the most sought after of the Seven Fortunes—for whether one is a lord or a peasant, one is sure to pray for health sooner or later. A shugenja can impart spiritual fortification in this Fortune’s name, anointing the body of the target with sacred earth, healing plants such as ginseng or rhubarb, or stranger remedies still. While under the effects of this blessing, a character is much more resistant to poison, disease, and the effects of alcohol—which can be a boon or curse depending on one&#x27;s goals.</li><li>As a Support action, make a TN 1 Theology (Earth) check targeting one character at range 0-1.</li><li>If you succeed, you augment your target&#x27;s fortitude. The target reduces TN of all checks to resist poison and disease by 2 (min 1). The target cannot become intoxicated via alcohol. Persists until end of the scene.</li><li>Earth (op): Target also reduces TN of checks to resist Mahō, Defiled terrain, and effects of Otherworldly beings by 2 (min 1).</li><li>Earth (op)(op): This effect persists for twenty-four hours instead.</li><li>Earth (op)(op): You also mend your target, removing current poisons, the Dying condition, and suppressing disease symptoms until end of scene.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":199},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.0EBHFNImBXL4y84I","skill":"theology"},{"name":"The Rushing Wave","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"invocation","rank":1,"description":"<ul><li>The shugenja calls the torrent as their steed and rides it, pulling a wave of water from a nearby lake, pond, river, or ocean to propel them forward at incredible speed.</li><li>As a Movement action, make a TN 2 Theology (Water) check targeting one character at range 0-1. Must have a large source of water nearby.</li><li>If you succeed during a skirmish, you summon a rushing waterspout that propels the target. The target may immediately move 1 range band, plus additional range bands equal to bonus successes.</li><li>If you succeed during a narrative or downtime scene, you summon a gentle current that doubles the target&#x27;s speed across or through water. Persists until end of scene.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":211},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.peUicL1zqfsDAieg","skill":"theology"},{"name":"Commune with the Spirits","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"ritual","rank":1,"description":"<ul><li>The ritualist centers their mind on one of the Elements, appealing to the spirits in their environment and seeking their counsel or boon. Priests and laypeople are able to use this ritual to receive less specific guidance from the spirits, such as a leaf that falls to the ground pointing in the direction of the person or thing they are seeking.</li><li>As a downtime activity or Support action, make a TN 1 Theology check using Air, Earth, Fire, Water, or Void to appeal to nearby spirits of that Element (appeal to the departed, such as ancestor spirits, and other non-elemental supernatural presences if using Void) for aid.</li><li>If you succeed, choose and receive one of the following boons: (1) Sense the Kami — Detect all spirits and uses of their magic by shugenja within a number of range bands equal to the ring you used plus your bonus successes. (2) Spiritual Knowledge — Learn one fact the spirits know about the area. (3) Elemental Gift — The kami deliver a small amount of the Element in question to you (e.g., rain from water kami, sparks from fire kami, a gust from air kami, a stone from earth kami, or a found ancestor&#x27;s belonging from Void).</li><li>(op): Reduce the TN of your next check to interact with or appeal to kami or supernatural presences of this Element by 1.</li><li>(op)+: If you succeed, receive one additional boon per (op) spent this way. Each boon can only be received one time per activation.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":212},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.r9DyFb62vtLwexbW","skill":"theology"},{"name":"Ancestry Unearthed","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":1,"description":"<ul><li>A samurai’s ancestry often reveals a great deal about their political opportunities, assets, and probable allies in the Emerald Empire, for the rigid social strata allow little divergence. Any courtier can likely dredge up another samurai’s lineage from the dark corners of their mind, but some can recall it in an instant.</li><li>When you make a Scholar skill (Earth) or Social skill (Earth) check targeting a character, you may spend (op) as follows:</li><li>Earth (op): You know one sworn oath the character&#x27;s family took in the past, and whether or not they have broken or bent it.</li><li>Earth (op)(op): You know one secret of the character&#x27;s family that they would prefer be forgotten, and have perhaps even worked to bury.</li><li>Earth (op)(op)(op): You know something the character does not even know about their own ancestry.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.rOlgMlOHnT3p7aIG"},{"name":"The Way of Names","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<ul><li>As a downtime activity, you may make a TN 2 Design check using any ring to bind a spirit to an inanimate vessel, creating a meishōdō talisman for one invocation of that Element that you have learned. While you have the talisman in your possession, reduce the TN of checks to activate that invocation by 1. You can give the talisman to another shugenja, allowing them to perform that invocation even if they have not learned it and reducing the TN to activate it by 1, but the talisman ceases to function after a number of uses equal to your school rank.</li><li>You can sustain a number of meishōdō talismans up to your school rank. You can only have one meishōdō talisman for any single invocation.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":83},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.CAr1w8KmAu1CGBrY"},{"name":"Sight beyond Existence","xp_used":0,"xp_cost":6,"in_curriculum":false,"bought_at_rank":0,"kind":"inversion","rank":1,"description":"<ul><li>Activation: Once per session, immediately after an action of great consequence, TN 2 Theology (Void), target that character at range 0-3</li><li>Scry for another outcome; return to the moment before the action; all effects undone; only you and target are aware. If you are the target, choose same or different action. If another character is the target, say up to five words before they act</li><li>Magnitude: 1+: see one consequence before end of scene; 2+: see consequence in next year; 3+: see consequence in decades</li></ul>","text_source":"dsl","source":{"book":"celestial_realms","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-inversions-l5r-sortilege.Item.2AUf2kuJdMWvY13L","skill":"theology"}],"peculiarities":[{"name":"Famously Reliable","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"earth","types":"Fame, Interpersonal","description":"<ul><li>Other people have heard of you for your remarkable adherence to your oaths and responsibilities, even over and above most samurai, and they believe it by default unless given evidence to the contrary.</li><li>When performing a check for which you need to leverage your reputation for keeping your oaths and bargains (such as a Command [Earth] check to calm a panicked soldier or a Performance [Earth] check to relate a tale that inspires patience), you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":104},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.DWrZtBuyK83Ah3a7"},{"name":"Encompassing Duty","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"earth","types":"Mental","description":"<ul><li>You have a duty to something (family, friend, cause). You have difficulty relaxing or focusing on unrelated tasks.</li><li>When making a check related to overcoming hindrance to your duty (such as Meditation [Earth] to stay calm in ambush or Courtesy [Earth] to reason with stubborn shopkeeper), you must choose and reroll two dice containing success or explosion. If you failed, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"path_of_waves","page":72},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.TP83fjX8gnxELunG"},{"name":"Hot Pot","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"earth","types":"Interpersonal, Physical","description":"<ul><li>You can prepare hearty communal meals and identify ingredients.</li><li>After performing a check involving the preparation of a communal meal, you remove 3 strife.</li></ul>","text_source":"dsl","source":{"book":"children_of_the_five_winds","page":94},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.WOcP34kHfJDLnn2W"},{"name":"Conspiracy","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"earth","types":"Interpersonal, Mental","description":"<ul><li>Plagued by knowledge of greater plots; you are constantly suspicious of authority figures.</li><li>After performing a check to interact with an unfamiliar authority figure, you receive 3 strife. If this is the first time this scene, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"celestial_realms","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.wBeHgMqK2BL7fX6I"},{"name":"Skilled Midwife","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"fire","types":"Interpersonal","description":"<ul><li>Exceptionally skilled in most aspects of pregnancy, childbirth, common illnesses children are prone to, and child-rearing. Others are more likely to take your advice regarding such matters.</li><li>When performing a check for which your midwife skills are a benefit (such as Culture [Fire] or Fitness [Fire]), you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"writ_of_the_wild","page":102},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.4Qw2aBKfrLpkqeyO"}],"titles":[],"bonds":[],"signature_scrolls":[],"gear":[{"name":"Wakizashi","quantity":1,"description":"<p>Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Horsebow","quantity":1,"description":"<p>Among the Unicorn Clan’s many adopted weapons is a small, sturdy bow used by the nomadic peoples of the steppes far to the west. Called the Shinjo horsebow in Rokugan, this weapon is a compact bow designed to be fired from the back of a moving horse. It is a short-range weapon intended for raiding and cavalry attacks.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":236},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.dqFV99QlfoFGklLg","damage":4,"deadliness":5,"range":"2-4","grip_1":"N/A","skill":"ranged","category":"Bows","rarity":"4","zeni":"6 koku","properties":[{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Ceremonial Clothes","quantity":1,"description":"<p>Ceremonial clothing is any garment worn during an official ceremony, from a samurai’s court kimono to the accoutrement of the Imperial family. Ceremonial clothing is often richly decorated and offers little protection.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.K61XHG9GnFLieqjc","armor":{"physical":1,"supernatural":0},"rarity":"4","zeni":"1 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000010","name":"Resplendent"}]},{"name":"Traveling Clothes","quantity":1,"description":"<p>Traveling clothes ordinarily consist of roughspun garments designed to resist wear and tear. They can be anything from robes to a kimono or jacket and leggings and are often accentuated with a hat or cloak.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.zcsgspz4VluSMeI0","armor":{"physical":2,"supernatural":0},"rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000012","name":"Mundane"},{"id":"L5RCorePro000016","name":"Subtle"}]},{"name":"Calligraphy Set","quantity":1,"description":"<p>These ornate boxes contain items a practiced callig- rapher needs to craft books, letters, scrolls, and other written communications. It consists of a small wooden box that contains a variety of brushes, inkstones, and pigments; a small bowl for water; and a small bag of sand for drying. Calligraphers and scribes customari- ly carry a calligraphy set, as so do some samurai and courtiers who prefer to write their own correspon- dence.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.MWzx5Wiu6xcCWc9J","rarity":"3","zeni":"1 bu"},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","text_source":"foundry","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Maker's Punch","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Herbal Medicines","quantity":1,"description":"<ul><li>Category: Shinobi Item</li><li>Cost: 1 bu per dose</li><li>Rarity: 5</li><li>At end of scene, character with Exhausted condition may use one dose to remove strife and fatigue as if not Exhausted. Cannot benefit again until Exhausted removed.</li></ul>","text_source":"dsl","source":{"book":"court_of_stones","page":107},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.1pTkf5gCBin24vP1","rarity":"5","zeni":"1 bu per dose"}],"gear_patterns":[]},{"xp":104,"label":null,"rank":4,"school":"Iuchi Meishodo Master School","foundry_id":"JmyWJBtsDzEzhsey","rings":{"air":1,"earth":2,"fire":5,"water":3,"void":4},"skills":{"artisan":{"aesthetics":1,"composition":0,"design":3,"smithing":3},"martial":{"fitness":0,"melee":0,"ranged":0,"unarmed":0,"meditation":0,"tactics":0},"scholar":{"culture":0,"government":0,"medicine":1,"sentiment":1,"theology":2},"social":{"command":0,"courtesy":1,"games":0,"performance":0},"trade":{"commerce":0,"labor":0,"seafaring":0,"skulduggery":0,"survival":3}},"social":{"honor":40,"glory":46,"status":33,"ninjo":"She wants children and has not been able to have them.","giri":"Her giri is to Shinjo Altansarnai, Khan of Khans and daimyō of the Shinjo: she makes meishōdō for the family's own use, issued where they are needed rather than given where they are wanted.","bushido_tenets":{"paramount":"Compassion","less_significant":"Honour"}},"derived":{"endurance":14,"composure":10,"focus":6,"vigilance":2,"void_points":4},"money":{"zeni":0,"koku":8,"bu":0},"advancements":[{"label":"Courtesy +1 (0 -> 1)","type":"skill","skill":"courtesy","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Void +1 (1 -> 2)","type":"ring","ring":"void","at_rank":1,"xp":6,"in_curriculum":false},{"label":"Void +1 (2 -> 3)","type":"ring","ring":"void","at_rank":1,"xp":9,"in_curriculum":false},{"label":"Fire +1 (3 -> 4)","type":"ring","ring":"fire","at_rank":1,"xp":12,"in_curriculum":false},{"label":"Void +1 (3 -> 4)","type":"ring","ring":"void","at_rank":2,"xp":12,"in_curriculum":false},{"label":"Fire +1 (4 -> 5)","type":"ring","ring":"fire","at_rank":2,"xp":15,"in_curriculum":false},{"label":"Design +1 (1 -> 2)","type":"skill","skill":"design","ring":"void","at_rank":2,"xp":4,"in_curriculum":true},{"label":"Design +1 (2 -> 3)","type":"skill","skill":"design","ring":"void","at_rank":3,"xp":6,"in_curriculum":true},{"label":"Smithing +1 (1 -> 2)","type":"skill","skill":"smithing","ring":"void","at_rank":3,"xp":4,"in_curriculum":true},{"label":"Survival +1 (2 -> 3)","type":"skill","skill":"survival","ring":"void","at_rank":3,"xp":6,"in_curriculum":true},{"label":"Smithing +1 (2 -> 3)","type":"skill","skill":"smithing","ring":"void","at_rank":3,"xp":6,"in_curriculum":true},{"label":"Theology +1 (1 -> 2)","type":"skill","skill":"theology","ring":"void","at_rank":3,"xp":4,"in_curriculum":true}],"techniques":[{"name":"Jurōjin’s Balm","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"invocation","rank":1,"description":"<ul><li>Jurōjin, guardian of longevity, health, and physical wellbeing, is one of the most sought after of the Seven Fortunes—for whether one is a lord or a peasant, one is sure to pray for health sooner or later. A shugenja can impart spiritual fortification in this Fortune’s name, anointing the body of the target with sacred earth, healing plants such as ginseng or rhubarb, or stranger remedies still. While under the effects of this blessing, a character is much more resistant to poison, disease, and the effects of alcohol—which can be a boon or curse depending on one&#x27;s goals.</li><li>As a Support action, make a TN 1 Theology (Earth) check targeting one character at range 0-1.</li><li>If you succeed, you augment your target&#x27;s fortitude. The target reduces TN of all checks to resist poison and disease by 2 (min 1). The target cannot become intoxicated via alcohol. Persists until end of the scene.</li><li>Earth (op): Target also reduces TN of checks to resist Mahō, Defiled terrain, and effects of Otherworldly beings by 2 (min 1).</li><li>Earth (op)(op): This effect persists for twenty-four hours instead.</li><li>Earth (op)(op): You also mend your target, removing current poisons, the Dying condition, and suppressing disease symptoms until end of scene.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":199},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.0EBHFNImBXL4y84I","skill":"theology"},{"name":"The Rushing Wave","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"invocation","rank":1,"description":"<ul><li>The shugenja calls the torrent as their steed and rides it, pulling a wave of water from a nearby lake, pond, river, or ocean to propel them forward at incredible speed.</li><li>As a Movement action, make a TN 2 Theology (Water) check targeting one character at range 0-1. Must have a large source of water nearby.</li><li>If you succeed during a skirmish, you summon a rushing waterspout that propels the target. The target may immediately move 1 range band, plus additional range bands equal to bonus successes.</li><li>If you succeed during a narrative or downtime scene, you summon a gentle current that doubles the target&#x27;s speed across or through water. Persists until end of scene.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":211},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.peUicL1zqfsDAieg","skill":"theology"},{"name":"Commune with the Spirits","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"ritual","rank":1,"description":"<ul><li>The ritualist centers their mind on one of the Elements, appealing to the spirits in their environment and seeking their counsel or boon. Priests and laypeople are able to use this ritual to receive less specific guidance from the spirits, such as a leaf that falls to the ground pointing in the direction of the person or thing they are seeking.</li><li>As a downtime activity or Support action, make a TN 1 Theology check using Air, Earth, Fire, Water, or Void to appeal to nearby spirits of that Element (appeal to the departed, such as ancestor spirits, and other non-elemental supernatural presences if using Void) for aid.</li><li>If you succeed, choose and receive one of the following boons: (1) Sense the Kami — Detect all spirits and uses of their magic by shugenja within a number of range bands equal to the ring you used plus your bonus successes. (2) Spiritual Knowledge — Learn one fact the spirits know about the area. (3) Elemental Gift — The kami deliver a small amount of the Element in question to you (e.g., rain from water kami, sparks from fire kami, a gust from air kami, a stone from earth kami, or a found ancestor&#x27;s belonging from Void).</li><li>(op): Reduce the TN of your next check to interact with or appeal to kami or supernatural presences of this Element by 1.</li><li>(op)+: If you succeed, receive one additional boon per (op) spent this way. Each boon can only be received one time per activation.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":212},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.r9DyFb62vtLwexbW","skill":"theology"},{"name":"Ancestry Unearthed","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":1,"description":"<ul><li>A samurai’s ancestry often reveals a great deal about their political opportunities, assets, and probable allies in the Emerald Empire, for the rigid social strata allow little divergence. Any courtier can likely dredge up another samurai’s lineage from the dark corners of their mind, but some can recall it in an instant.</li><li>When you make a Scholar skill (Earth) or Social skill (Earth) check targeting a character, you may spend (op) as follows:</li><li>Earth (op): You know one sworn oath the character&#x27;s family took in the past, and whether or not they have broken or bent it.</li><li>Earth (op)(op): You know one secret of the character&#x27;s family that they would prefer be forgotten, and have perhaps even worked to bury.</li><li>Earth (op)(op)(op): You know something the character does not even know about their own ancestry.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.rOlgMlOHnT3p7aIG"},{"name":"The Way of Names","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<ul><li>As a downtime activity, you may make a TN 2 Design check using any ring to bind a spirit to an inanimate vessel, creating a meishōdō talisman for one invocation of that Element that you have learned. While you have the talisman in your possession, reduce the TN of checks to activate that invocation by 1. You can give the talisman to another shugenja, allowing them to perform that invocation even if they have not learned it and reducing the TN to activate it by 1, but the talisman ceases to function after a number of uses equal to your school rank.</li><li>You can sustain a number of meishōdō talismans up to your school rank. You can only have one meishōdō talisman for any single invocation.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":83},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.CAr1w8KmAu1CGBrY"},{"name":"Sight beyond Existence","xp_used":0,"xp_cost":6,"in_curriculum":false,"bought_at_rank":0,"kind":"inversion","rank":1,"description":"<ul><li>Activation: Once per session, immediately after an action of great consequence, TN 2 Theology (Void), target that character at range 0-3</li><li>Scry for another outcome; return to the moment before the action; all effects undone; only you and target are aware. If you are the target, choose same or different action. If another character is the target, say up to five words before they act</li><li>Magnitude: 1+: see one consequence before end of scene; 2+: see consequence in next year; 3+: see consequence in decades</li></ul>","text_source":"dsl","source":{"book":"celestial_realms","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-inversions-l5r-sortilege.Item.2AUf2kuJdMWvY13L","skill":"theology"},{"name":"Sympathetic Energies","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"invocation","rank":2,"description":"<ul><li>Water kami flow through all living beings, and a shugenja can use their winding channels to transfer boons and curses alike between individuals.</li><li>As a Support action, make a TN 2 Theology (Water) check to spread one chosen persistent invocation effect across a number of targets equal to your Water Ring at range 0-1.</li><li>If you succeed, you augment the spiritual power of one persistent invocation effect already affecting one target. Each other target counts as being affected by it as well. Persists as long as the original effect persists on the original target.</li><li>Water (op)(op): Choose a condition the target is suffering instead of a persistent invocation effect.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":211},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.Gwjcwz5yreZTUbuv","skill":"theology"},{"name":"Cleansing Rite","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"ritual","rank":1,"description":"<ul><li>The ritualist sanctifies a person or group, anointing them with sacred substances that drive out unholy presences and malign sorcery.</li><li>As a downtime activity, make a TN 3 Theology (Void) check targeting up to five characters to remove spiritual contaminants from the targets before they spread. Note: this cannot remove a Shadowlands Taint disadvantage once it has taken hold, but it can prevent this spiritual contamination from taking root after a character is exposed.</li><li>If you succeed, remove the Afflicted condition from the target.</li><li>Void (op)(op): If one or more targets is an Otherworldly being, you become aware of it after completing the ritual — but you do not know which target.</li><li>Void (op)+: Choose one additional target per (op) spent this way.</li><li>Void (op)+: Instead of targeting characters, you may target an area encompassing a number of range bands around you equal to (op) spent this way. Remove the Defiled terrain quality from this area. If it is a deeply unhallowed place that has long been the domain of evil, the Defiled quality returns after one day, plus additional days equal to your bonus successes.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":212},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.1lVY0jhJAeEa4Byg","skill":"theology"},{"name":"Hands of the Tides","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"invocation","rank":3,"description":"<ul><li>Water binds all living beings, and by communing deeply with the vital spirits that flow through everything, a shugenja can master many arts. Using this esoteric invocation, a shugenja can exchange the positions of living beings near one another, throw enemies off-balance, or put allies in a position of advantage. While the Elemental Masters have been known to debate whether the water spirits shift the targets or reshape the world around them, the effect of the invocation—shuffling the positions of a number of individuals in a small radius as the shugenja sees fit—is easy to understand, if hard to comprehend.</li><li>As a Movement action, make a TN 5 Theology (Water) check targeting yourself and a number of other characters up to your Water Ring at range 1-4.</li><li>If you succeed, you summon the targets. You may cause them to exchange their positions in space. Each target&#x27;s original position must be occupied by a target, and each target must occupy a position.</li><li>Each target receives 2 strife.</li><li>Water +(op): Choose a new stance for one target per (op) spent this way.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":208},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.XlT1ii5rbeEZEm3F","skill":"theology"},{"name":"Courage of Seven Thunders","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"invocation","rank":1,"description":"<ul><li>At the dawn of the Empire, the Seven Thunders stood against Fu Leng, and their clash resounded from the Shadowlands to every corner of Rokugan. Earth is the Element of recollection, and from the earth kami, a shugenja can unearth fragments of the memories of these heroes from across the ages and impart them to their comrades in arms. This invocation does not erase fear, but it reminds a samurai of the legacy they must uphold—that others stood against the darkness before and prevailed.</li><li>As a Support action, make a TN 2 Theology (Earth) check targeting a number of characters up to your Earth Ring at range 0-2.</li><li>If you succeed, you augment each target with vigorous resolve; each target increases their composure by your Earth Ring. Persists until end of the scene.</li><li>Earth (op): Each target also increases their endurance by your Earth Ring while this effect persists.</li><li>Earth +(op): Each target removes 1 strife per (op) spent this way.</li><li>Earth (op)(op): This technique targets each friendly character in range instead.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":197},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.VUi6dvjC1LnwkvQ3","skill":"theology"},{"name":"Dazzling Performance","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"shuji","rank":3,"description":"<ul><li>Performing a great feat can win a character renown, but performing a great feat and then telling the story of it draws far greater accolades. A courtier building a reputation in the competitive courts of Rokugan must master not just excellence, but also capture the imagination.</li><li>When making an Artisan skill (Fire), Games (Fire), or Performance (Fire) check, you may spend (op) in the following way:</li><li>Fire (op)+: The next time you receive a glory award this scene, increase the amount you receive by 1. If there is a character of higher status in the scene, increase it by 1 per (op) spent this way instead.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":218},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.lmCMb0PMC4wlIDUn"},{"name":"Rise, Earth","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"invocation","rank":4,"description":"<ul><li>An earth kami bursts from the ground, manifesting as a guardian creature of living rock with veins of sapphire, ruby, or even jade. Earth kami can be cantankerous, but they hate anything tainted and strive to obliterate them.</li><li>As a Support action, make a TN 6 Theology (Earth) check targeting one position that includes dirt, clay, or stone at range 0-3.</li><li>If you succeed, you summon a Manifest Earth Kami to fight for you, which bursts forth at the target position. It obeys you for three rounds, plus additional rounds equal to bonus successes, taking its turn immediately after yours. When this effect ends, it departs or follows its own directives (will not attack you unless provoked).</li><li>Earth +(op): Increase the earth kami&#x27;s endurance by 2 per (op) spent this way.</li><li>Earth (op): The earth kami&#x27;s stone fists unarmed attack profile gains the Sacred quality.</li><li>Earth (op): The manifest earth kami creates a shockwave. Each character at range 0-2 of the chosen position must resist with a TN 4 Fitness check (Air 2, Water 5) or suffer physical or supernatural damage equal to your Earth Ring and Prone.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":200},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.IHvdbsCUhHTagGGa","skill":"theology"}],"peculiarities":[{"name":"Famously Reliable","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"earth","types":"Fame, Interpersonal","description":"<ul><li>Other people have heard of you for your remarkable adherence to your oaths and responsibilities, even over and above most samurai, and they believe it by default unless given evidence to the contrary.</li><li>When performing a check for which you need to leverage your reputation for keeping your oaths and bargains (such as a Command [Earth] check to calm a panicked soldier or a Performance [Earth] check to relate a tale that inspires patience), you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":104},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.DWrZtBuyK83Ah3a7"},{"name":"Encompassing Duty","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"earth","types":"Mental","description":"<ul><li>You have a duty to something (family, friend, cause). You have difficulty relaxing or focusing on unrelated tasks.</li><li>When making a check related to overcoming hindrance to your duty (such as Meditation [Earth] to stay calm in ambush or Courtesy [Earth] to reason with stubborn shopkeeper), you must choose and reroll two dice containing success or explosion. If you failed, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"path_of_waves","page":72},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.TP83fjX8gnxELunG"},{"name":"Hot Pot","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"earth","types":"Interpersonal, Physical","description":"<ul><li>You can prepare hearty communal meals and identify ingredients.</li><li>After performing a check involving the preparation of a communal meal, you remove 3 strife.</li></ul>","text_source":"dsl","source":{"book":"children_of_the_five_winds","page":94},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.WOcP34kHfJDLnn2W"},{"name":"Conspiracy","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"earth","types":"Interpersonal, Mental","description":"<ul><li>Plagued by knowledge of greater plots; you are constantly suspicious of authority figures.</li><li>After performing a check to interact with an unfamiliar authority figure, you receive 3 strife. If this is the first time this scene, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"celestial_realms","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.wBeHgMqK2BL7fX6I"},{"name":"Skilled Midwife","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"fire","types":"Interpersonal","description":"<ul><li>Exceptionally skilled in most aspects of pregnancy, childbirth, common illnesses children are prone to, and child-rearing. Others are more likely to take your advice regarding such matters.</li><li>When performing a check for which your midwife skills are a benefit (such as Culture [Fire] or Fitness [Fire]), you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"writ_of_the_wild","page":102},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.4Qw2aBKfrLpkqeyO"}],"titles":[],"bonds":[],"signature_scrolls":[],"gear":[{"name":"Wakizashi","quantity":1,"description":"<p>Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Horsebow","quantity":1,"description":"<p>Among the Unicorn Clan’s many adopted weapons is a small, sturdy bow used by the nomadic peoples of the steppes far to the west. Called the Shinjo horsebow in Rokugan, this weapon is a compact bow designed to be fired from the back of a moving horse. It is a short-range weapon intended for raiding and cavalry attacks.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":236},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.dqFV99QlfoFGklLg","damage":4,"deadliness":5,"range":"2-4","grip_1":"N/A","skill":"ranged","category":"Bows","rarity":"4","zeni":"6 koku","properties":[{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Ceremonial Clothes","quantity":1,"description":"<p>Ceremonial clothing is any garment worn during an official ceremony, from a samurai’s court kimono to the accoutrement of the Imperial family. Ceremonial clothing is often richly decorated and offers little protection.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.K61XHG9GnFLieqjc","armor":{"physical":1,"supernatural":0},"rarity":"4","zeni":"1 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000010","name":"Resplendent"}]},{"name":"Traveling Clothes","quantity":1,"description":"<p>Traveling clothes ordinarily consist of roughspun garments designed to resist wear and tear. They can be anything from robes to a kimono or jacket and leggings and are often accentuated with a hat or cloak.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.zcsgspz4VluSMeI0","armor":{"physical":2,"supernatural":0},"rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000012","name":"Mundane"},{"id":"L5RCorePro000016","name":"Subtle"}]},{"name":"Calligraphy Set","quantity":1,"description":"<p>These ornate boxes contain items a practiced callig- rapher needs to craft books, letters, scrolls, and other written communications. It consists of a small wooden box that contains a variety of brushes, inkstones, and pigments; a small bowl for water; and a small bag of sand for drying. Calligraphers and scribes customari- ly carry a calligraphy set, as so do some samurai and courtiers who prefer to write their own correspon- dence.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.MWzx5Wiu6xcCWc9J","rarity":"3","zeni":"1 bu"},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","text_source":"foundry","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Maker's Punch","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Herbal Medicines","quantity":1,"description":"<ul><li>Category: Shinobi Item</li><li>Cost: 1 bu per dose</li><li>Rarity: 5</li><li>At end of scene, character with Exhausted condition may use one dose to remove strife and fatigue as if not Exhausted. Cannot benefit again until Exhausted removed.</li></ul>","text_source":"dsl","source":{"book":"court_of_stones","page":107},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.1pTkf5gCBin24vP1","rarity":"5","zeni":"1 bu per dose"}],"gear_patterns":[]}]};
